var menuScrollPosition=0;function getScrollPosition(){return window.scrollY||window.scrollTop||document.getElementsByTagName("html")[0].scrollTop}function setMenuOpen(a){document.getElementById("site-nav").classList.toggle("open",a);document.querySelector(".nav-toggle").setAttribute("aria-expanded",a)}function foldMenu(){menuScrollPosition=getScrollPosition();setMenuOpen(!document.getElementById("site-nav").classList.contains("open"))}function closeMenuIfOpened(){setMenuOpen(false)}window.addEventListener("scroll",function(b){var a=getScrollPosition();if(Math.abs(a-menuScrollPosition)>250){closeMenuIfOpened()}});